<script setup lang="ts">
import { RouterLink } from 'vue-router'
import { replyLabels, type Letter } from '../../api/letters'
import BasisPreview from '../../shared/BasisPreview.vue'
defineProps<{ letter: Letter }>()
const controlLabels = { opened: 'Поставлен на контроль', deadline_changed: 'Срок изменён', closed: 'Контроль закрыт', reopened: 'Контроль возобновлён' }
function time(value: string) { return new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Krasnoyarsk', dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) }
</script>
<template>
  <section class="card stack-card"><h2>Регистрация</h2><template v-if="letter.registration"><p><strong>{{ letter.registration.registration_number }}</strong> · {{ letter.registration.journal.name }} · {{ letter.registration.registered_on }}</p><p class="muted compact">Редакция {{ letter.registration.revision_id }} · {{ letter.registration.actor.full_name }} · {{ time(letter.registration.created_at) }}</p><p>{{ letter.registration.reason }}</p><div data-registration-files><h3>Снимок приложений при регистрации</h3><BasisPreview v-for="(file, index) in letter.registration.files" :key="file?.id ?? index" :document="file" heading="Подтверждённое приложение при регистрации" accepted-label="При регистрации подтверждена" /><p v-if="!letter.registration.files.length" class="muted">Электронных приложений в снимке регистрации нет.</p></div></template><p v-else class="muted">Письмо пока не зарегистрировано.</p></section>
  <section data-dispatch-history class="card stack-card"><h2>Отправки</h2><div v-for="item in letter.dispatches" :key="item.id" class="assignment-line"><h3>{{ item.sent_on }} · {{ item.channel.name }}</h3><p>Адресаты: {{ letter.content.recipients.filter(recipient => item.recipient_ids.includes(recipient.id)).map(recipient => recipient.name).join(', ') }}</p><p v-if="item.tracking">Трек: {{ item.tracking }}</p><p>{{ item.comment }}</p><p>{{ item.reason }}</p><small>{{ item.actor.full_name }} · {{ time(item.created_at) }}</small><BasisPreview v-if="item.evidence" :document="item.evidence" heading="Подтверждение отправки" accepted-label="При записи отправки подтверждена" /><div><h4>Снимок отправленных приложений</h4><BasisPreview v-for="(file, index) in item.files" :key="file?.id ?? index" :document="file" heading="Отправленное приложение" accepted-label="При отправке подтверждена" /><p v-if="!item.files.length" class="muted">Электронные файлы не зафиксированы в этой отправке.</p></div></div><p v-if="!letter.dispatches.length" class="muted">Фактических отправок не зафиксировано.</p></section>
  <section data-delivery-history class="card stack-card"><h2>Подтверждённые доставки</h2><div v-for="item in letter.deliveries" :key="item.id" class="assignment-line"><h3>{{ item.delivered_on }} · {{ letter.content.recipients.find(recipient => recipient.id === item.recipient_id)?.name || 'Адресат' }}</h3><p>Отправка: {{ letter.dispatches.find(dispatch => dispatch.id === item.dispatch_id)?.sent_on || 'Неизвестно' }}</p><p>{{ item.reason }}</p><small>{{ item.actor.full_name }} · {{ time(item.created_at) }}</small><BasisPreview v-if="item.evidence" :document="item.evidence" heading="Подтверждение доставки" accepted-label="При записи доставки подтверждена" /></div><p v-if="!letter.deliveries.length" class="muted">Доставка не подтверждена. Факт отправки не подтверждает доставку.</p></section>
  <section class="card stack-card"><h2>Факты получения</h2><div v-for="item in letter.receipts" :key="item.id" class="assignment-line"><h3>{{ item.received_on }}</h3><p>{{ item.reason }}</p><small>{{ item.actor.full_name }} · {{ time(item.created_at) }}</small><BasisPreview v-if="item.evidence" :document="item.evidence" heading="Подтверждение получения" accepted-label="При записи получения подтверждена" /></div><p v-if="!letter.receipts.length" class="muted">Подтверждённых фактов получения нет.</p></section>
  <section v-if="letter.control" data-control-history class="card stack-card"><h2>История контроля</h2><div v-for="item in letter.control.events" :key="item.id" class="assignment-line"><h3>{{ controlLabels[item.kind] }} · {{ item.actual_on }}</h3><p>Срок: {{ item.due_on || 'Неизвестен' }} {{ item.due_basis }}</p><p v-if="item.closure_reason">Основание закрытия: {{ item.closure_reason.name }}</p><p v-if="item.reply"><span v-if="'restricted' in item.reply">Доступ к ответу ограничен.</span><RouterLink v-else :to="`/letters/${item.reply.id}`">{{ item.reply.subject || 'Ответ' }}</RouterLink></p><p>{{ item.comment }}</p><p>{{ item.reason }}</p><small>{{ item.actor.full_name }} · {{ time(item.created_at) }}</small></div></section>
  <section class="card stack-card"><h2>История ответственных</h2><div v-for="item in letter.assignment_history" :key="item.id" class="assignment-line"><h3>{{ item.previous?.full_name || 'Не указан' }} → {{ item.responsible.full_name }}</h3><p>{{ item.reason }}</p><small>{{ item.actor.full_name }} · {{ time(item.created_at) }}</small></div><p v-if="!letter.assignment_history.length" class="muted">Переназначений нет.</p></section>
  <section data-content-history class="card stack-card"><h2>Редакции содержания</h2><details v-for="item in letter.content_history" :key="item.id" class="assignment-line"><summary>Редакция {{ item.number }} · {{ item.subject || 'Без темы' }} · {{ time(item.created_at) }}</summary><p>{{ item.kind?.name || 'Вид не указан' }} · {{ item.reply_completeness ? replyLabels[item.reply_completeness] + ' ответ' : 'Полнота ответа не указана' }}</p><p class="letter-text">{{ item.body || 'Содержание не указано' }}</p><dl class="work-facts"><div><dt>Отправитель</dt><dd>{{ item.sender_name || 'Не указан' }}</dd></div><div><dt>Внешние реквизиты</dt><dd>{{ item.external_number || 'Номер неизвестен' }} · {{ item.external_on || 'Дата неизвестна' }}</dd></div><div><dt>Дата документа</dt><dd>{{ item.document_on || 'Неизвестно' }}</dd></div><div><dt>Получено (в редакции)</dt><dd>{{ item.received_on || 'Неизвестно' }}</dd></div></dl><p v-for="recipient in item.recipients" :key="recipient.id">{{ recipient.name }} · {{ recipient.address }} · {{ recipient.email }}</p><p v-if="item.material">Материал: {{ item.material.title }}</p><p v-if="item.expertises.length">Работы: {{ item.expertises.map(work => work.registration_number).join(', ') }}</p><p>{{ item.note }}</p><p>{{ item.reason }}</p><small>{{ item.actor.full_name }}</small></details></section>
</template>
